	_, err := o.Raw(query, params...).QueryRows(&results)
	if err != nil {
		return nil, fmt.Errorf("failed to generate user activity report: %w", err)
	}

	if results == nil {
		results = []UserActivitySummary{}
	}

	return results, nil
}

// DepartmentReportRow represents a row in the department report.
type DepartmentReportRow struct {
	GroupValue      string
	UserCount       int
	TotalActivities int
}

// GenerateDepartmentReport creates a summary report grouped by a specified field.
func GenerateDepartmentReport(o orm.Ormer, departments []string, groupByField string) ([]map[string]interface{}, error) {
	if len(departments) == 0 {
		return []map[string]interface{}{}, nil
	}

	// Validate groupByField to prevent SQL injection
	validFields := map[string]bool{
		"department":   true,
		"role":         true,
		"display_name": true,
	}

	if !validFields[groupByField] {
		return nil, fmt.Errorf("invalid groupByField: %s, must be one of: department, role, display_name", groupByField)
	}

	// Build placeholders for IN clause
	placeholders := make([]string, len(departments))
	params := make([]interface{}, len(departments))

