		LEFT JOIN user_activity a ON u.id = a.user_id
		WHERE u.department IN (%s)
		GROUP BY u.%s
		ORDER BY u.%s
	`, groupByField, strings.Join(placeholders, ","), groupByField, groupByField)

	var rows []DepartmentReportRow
	_, err := o.Raw(query, params...).QueryRows(&rows)
	if err != nil {
		return nil, fmt.Errorf("failed to generate department report: %w", err)
	}

	results := make([]map[string]interface{}, 0, len(rows))
	for _, row := range rows {
