// RegisterUser creates a new user profile and inserts it into the database.
func RegisterUser(o orm.Ormer, username, displayName, email, department, role string) (*UserProfile, error) {
	profile := &UserProfile{
		Username:    username,
		DisplayName: displayName,
		Email:       email,
		Department:  department,
		Role:        role,
	}

	id, err := o.Insert(profile)
	if err != nil {
		return nil, fmt.Errorf("failed to insert user profile: %w", err)
	}

	profile.Id = id
	return profile, nil
}

// GenerateUserActivityReport creates an activity report for specified users.
func GenerateUserActivityReport(o orm.Ormer, usernames []string, actionTypeFilter string, startDate, endDate time.Time) ([]UserActivitySummary, error) {
	if len(usernames) == 0 {
		return []UserActivitySummary{}, nil
	}

	// Build placeholders for IN clause
	placeholders := make([]string, len(usernames))
	params := make([]interface{}, 0, len(usernames)+2)

	for i, username := range usernames {
		placeholders[i] = "?"
		params = append(params, username)
	}

	params = append(params, startDate, endDate)

	query := fmt.Sprintf(`
		SELECT u.display_name, a.action_type, 
		       COUNT(*) as total, 
		       SUM(CASE WHEN a.success THEN 1 ELSE 0 END) as success_count, 
		       AVG(a.duration_ms) as avg_duration
		FROM user_activity a 
		JOIN user_profile u ON a.user_id = u.id
		WHERE u.username IN (%s) 
		  AND a.created_at >= ? 
		  AND a.created_at <= ?
	`, strings.Join(placeholders, ","))

	if actionTypeFilter != "" {
		query += " AND a.action_type = ?"
		params = append(params, actionTypeFilter)
	}

	query += " GROUP BY u.display_name, a.action_type"

	var results []UserActivitySummary
	_, err := o.Raw(query, params...).QueryRows(&results)
	if err != nil {
		return nil, fmt.Errorf("failed to generate user activity report: %w", err)
	}

	if results == nil {
		results = []UserActivitySummary{}
	}

	return results, nil
}

// GenerateDepartmentReport creates a summary report grouped by a specified field.
func GenerateDepartmentReport(o orm.Ormer, departments []string, groupByField string) ([]map[string]interface{}, error) {
	if len(departments) == 0 {
		return []map[string]interface{}{}, nil
	}

	// Validate groupByField to prevent SQL injection
	allowedFields := map[string]bool{
		"department":   true,
		"role":         true,
		"display_name": true,
	}

	if !allowedFields[groupByField] {
		return nil, fmt.Errorf("invalid groupByField: %s, must be one of: department, role, display_name", groupByField)
	}

	// Build placeholders for IN clause
	placeholders := make([]string, len(departments))
	params := make([]interface{}, len(departments))

	for i, dept := range departments {
		placeholders[i] = "?"
		params[i] = dept
	}

	query := fmt.Sprintf(`
		SELECT u.%s as group_value, 
		       COUNT(DISTINCT u.id) as user_count, 
		       COUNT(a.id) as total_activities
		FROM user_profile u
		LEFT JOIN user_activity a ON u.id = a.user_id
		WHERE u.department IN (%s)
		GROUP BY u.%s
	`, groupByField, strings.Join(placeholders, ","), groupByField)

	var rows []orm.Params
	_, err := o.Raw(query, params...).Values(&rows)
	if err != nil {
		return nil, fmt.Errorf("failed to generate department report: %w", err)
	}

	results := make([]map[string]interface{}, 0, len(rows))
	for _, row := range rows {
		result := make(map[string]interface{})
		for k, v := range row {
			result[k] = v
		}
		results = append(results, result)
	}

	return results, nil
}

